class Box<T> {
    private final T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
}

class Main {
    public static void main(String[] args) throws Exception {
        Box<String> room = new Box<>("Lab");
        Box<Integer> seats = new Box<>(30);
        System.out.println(room.get().length());
        System.out.println(seats.get() + 2);
    }
}

import java.util.List;



class Main {
    static <T extends Number> double total(List<T> values) {
        double sum = 0;
        for (T value : values) { sum += value.doubleValue(); }
        return sum;
    }
    public static void main(String[] args) throws Exception {
        System.out.println(total(List.of(2, 3)));
        System.out.println(total(List.of(1.5, 2.5)));
    }
}

import java.util.List;
import java.util.ArrayList;



class Main {
    static <T> void copy(List<? extends T> source, List<? super T> target) {
        for (T value : source) { target.add(value); }
    }
    public static void main(String[] args) throws Exception {
        List<Integer> source = List.of(4, 7);
        List<Number> target = new ArrayList<>();
        copy(source, target);
        System.out.println(target);
    }
}
